class Solution {
public:
    double averageWaitingTime(vector<vector<int>>& customers) {
        long long curFree = 0;
        long long totalWait = 0;
        int n = customers.size();
        for (int i = 0; i < n; i++) {
            long long arrival = customers[i][0];
            long long time = customers[i][1];
            long long start = max(curFree, arrival);
            long long finish = start + time;
            totalWait += finish - arrival;
            curFree = finish;
        }
        return (double)totalWait / n;
    }
};
